/* eslint-disable @stencil-community/ban-default-true */
import { Component, Element, EventEmitter, h, Prop, Event, Host, ComponentInterface } from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { DetailArgs } from '@src/shared/dom';
import { TimezoneInfo } from '@src/shared/timezone';
import { Placement } from '@floating-ui/dom';
import { Slot, Slots, Vue2ValueFix } from '@src/framework/decorators';
import {
  DatePickerComparisonProps,
  DatePickerViewMode,
  DatePresetOptions,
  DateValue,
  ValueChangeInfo,
  ComparisonChangeInfo,
  DateTimeFormatOptions,
} from '../types';

/**
 * Flat naming with consistent prefixes optimizes both tree-shaking efficiency and developer search-to-usage speed.
 * @slot popupExtraFooter - Slot for an extra footer above the default footer.
 * @slot popupFooterAppend - Slot inside the footer of the popup.
 * @slot prefix - Slot for prefix content such as a fiscal-year label inside the trigger field.
 */
@Component({
  tag: 'ks-date-range-picker-quarter',
  styleUrl: 'common.scss',
  shadow: true,
})
export class KsDateRangePickerQuarter implements ComponentInterface {
  @Element() el!: HTMLKsDateRangePickerQuarterElement;

  // ══════════════════════════════════════════════════════════════════════════
  //  [➡️ External As-is] External API Props (Pass-through)
  // ══════════════════════════════════════════════════════════════════════════

  /** If true, a clear button is shown when the input has a value and is focused, allowing the user to clear the content. */
  @Prop() clearable = true;
  /** Sets the validation status of the input, affecting its visual style (e.g., 'error', 'warning'). */
  @Prop() status?: Status;
  /** The timezone info. Defaults to the global `timezone` setting of `Keystone.config()`. */
  @Prop() timezone?: TimezoneInfo;
  /** Controls whether the timezone indicator is shown. Pass `true` for the default input placement, or an object to customize the indicator `placement` and `style`. */
  @Prop() showTimezone?: boolean | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' } = false;
  /** The placement of the popover relative to the picker input. */
  @Prop() placement: Placement = 'bottom-start';
  /** The open state of the selection popup of the picker. */
  @Prop() open?: boolean;
  /** The default open state of the selection popup of the picker. */
  @Prop() defaultOpen = false;
  /** When `true`, the picker will need clicking a confirm button to apply the selection. */
  @Prop() needConfirm = false;
  /** Whether or not to show the cancel button in the popup footer, commonly used when `needConfirm` is `true`. */
  @Prop() showCancel = false;

  /** The anchor date used to navigate the calendar panel view. The panel will display the calendar page (e.g., month, year) that contains this date. */
  @Prop() viewDate?: DateValue;
  /** Disables specific quarter-range values or preset options. The callback receives the current `date` string plus an `info` object describing whether the source is a calendar date or a preset. */
  @Prop() disabledDate?: (
    date: DateValue,
    info: { type: 'date' | 'preset'; from?: DateValue; to?: DateValue; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  /** Emitted when the clear button is clicked. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;
  /** Emitted when the open state changes. Emits the new open state as a boolean. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;
  /** Emitted when the `viewDate` changes. */
  @Event({ bubbles: false, composed: false }) ksViewDateChange!: EventEmitter<DateValue>;
  /** Emitted when the `viewMode` changes. */
  @Event({ bubbles: false, composed: false }) ksViewModeChange!: EventEmitter<DatePickerViewMode>;

  // @Slot({ slotname: 'footer' }) private footerSlot?: Slots;

  // ══════════════════════════════════════════════════════════════════════════
  //  [↪️ External Adapted] External API Props (Needs Adaptation)
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * The selected quarter range value. Each tuple item represents one boundary of the range, and `null` means that boundary is currently unset.
   *
   * @note As we have many systems with customized timezone implementations, using a **timezone-agnostic** `value` is more accurate and robust.
   */
  @Prop() @Vue2ValueFix() value?: [DateValue | null, DateValue | null];
  /** The default selected value, used in uncontrolled mode. */
  @Prop() defaultValue?: [DateValue | null, DateValue | null] = [null, null];
  /** Placeholder text for the quarter range field. Pass a single string to reuse it for both inputs, or a tuple to configure the start and end placeholders separately. */
  @Prop() placeholder?: string | undefined | [string | undefined, string | undefined];
  /** Controls whether the quarter range picker is disabled. Pass a single boolean to disable both inputs, or a tuple to control the start and end fields independently. */
  @Prop() disabled?: boolean | [boolean, boolean];
  /**
   * Configures the Date Picker's comparison feature.
   * To ensure predictable state management for this advanced feature, it operates in a **fully controlled mode**.
   * The parent component is responsible for managing this state and passing it back via props in response to the `onComparisonChange` event.
   */
  @Prop() comparison?: DatePickerComparisonProps;
  /** Controls the current panel view mode of the quarter range picker, such as `quarterInYear` or `yearInDecade`. */
  @Prop() viewMode?: DatePickerViewMode;
  /** Sets the initial panel view mode when the quarter range picker is uncontrolled. */
  @Prop() defaultViewMode: DatePickerViewMode = 'quarterInYear';
  /** The available view modes of the quarter range picker. These modes remain navigable from the panel header. */
  @Prop() availableViewModes: DatePickerViewMode[] = ['quarterInYear', 'yearInDecade'];
  /** Configures how the selected quarter range is displayed in the trigger field, such as quarter and year labels. */
  @Prop() displayFormatOptions: DateTimeFormatOptions = { quarter: 'short', year: 'numeric' };
  /**
   * The format of the `value` prop string. Used for parsing the `value` prop.
   * @note As we have many systems with customized timezone implementations, use **timezone-agnostic** `value` is more accurate and robust.
   */
  @Prop() format?: string = 'YYYY-[Q]Q';
  /** Configures the preset options of the quarter range picker. When `true`, the default preset options are enabled. */
  @Prop() presets: boolean | { options: DatePresetOptions } = false;

  /** Emitted when the selected quarter range changes. Emits the updated `[start, end]` tuple, and uses `null` for any unset boundary. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[[DateValue | null, DateValue | null], info: ValueChangeInfo]>
  >;
  /** Emitted when interactions in the Date Picker's comparison feature propose an update to `comparison`. */
  @Event({ bubbles: false, composed: false }) ksComparisonChange!: EventEmitter<
    DetailArgs<[DatePickerComparisonProps, info: ComparisonChangeInfo]>
  >;
  /** Emitted when the user picks a comparison value, even if not confirmed yet. */
  @Event({ bubbles: false, composed: false }) ksComparisonPick!: EventEmitter<
    DetailArgs<[DatePickerComparisonProps, info: ComparisonChangeInfo]>
  >;

  @Slot({ slotname: 'popupExtraFooter' }) private popupExtraFooterSlot?: Slots;
  @Slot({ slotname: 'popupFooterAppend' }) private popupFooterAppendSlot?: Slots;
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  render() {
    return (
      <Host class="KsDateRangePicker">
        <ks-date-time-picker-adapter
          exportparts="fieldTimezone"
          clearable={this.clearable}
          status={this.status}
          timezone={this.timezone}
          showTimezone={this.showTimezone}
          placement={this.placement}
          open={this.open}
          defaultOpen={this.defaultOpen}
          presets={this.presets}
          needConfirm={this.needConfirm}
          showCancel={this.showCancel}
          viewDate={this.viewDate}
          disabledDate={this.disabledDate}
          onKsClear={() => this.ksClear.emit()}
          onKsOpenChange={({ detail }) => this.ksOpenChange.emit(detail)}
          onKsViewDateChange={({ detail }) => this.ksViewDateChange.emit(detail)}
          onKsViewModeChange={({ detail }) => this.ksViewModeChange.emit(detail)}
          onKsComparisonChange={({ detail }) => this.ksComparisonChange.emit(detail)}
          onComparisonPick={(comparison, info) => this.ksComparisonPick.emit(DetailArgs(comparison, info))}
          value={this.value}
          defaultValue={this.defaultValue}
          placeholder={this.placeholder}
          disabled={this.disabled}
          comparison={this.comparison}
          viewMode={this.viewMode}
          defaultViewMode={this.defaultViewMode}
          availableViewModes={this.availableViewModes}
          displayFormatOptions={this.displayFormatOptions}
          format={this.format}
          onKsChange={({ detail }) =>
            this.ksChange.emit(detail as DetailArgs<[[DateValue | null, DateValue | null], info: ValueChangeInfo]>)
          }
          isRange={true}
          displayMode="dual"
          rangeSelectionMode="direct"
          data-testid="pickers-date-range-picker-sVnxPk"
        >
          {this.popupExtraFooterSlot && <slot name="popupExtraFooter" slot="popupExtraFooter"></slot>}
          {this.popupFooterAppendSlot && <slot name="popupFooterAppend" slot="popupFooterAppend"></slot>}
          {this.prefixSlot && <slot name="prefix" slot="prefix"></slot>}
        </ks-date-time-picker-adapter>
      </Host>
    );
  }
}
